<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import { getPublicPositions, submitQuestionnaire, getQuestionnaireInvitation, submitQuestionnaireInvitation } from '@/api/candidate'
import BrandLockup from '@/components/BrandLockup.vue'
import TalentChoiceGroup from '@/components/TalentChoiceGroup.vue'

const route = useRoute()
const token = computed(() => String(route.query.token || ''))
const form = reactive({ name: '', nickname: '', gender: '', phone: '', wechat: '', email: '', source: '', applyTime: new Date().toISOString().slice(0, 10), jobId: '', salaryMin: '', salaryMax: '', location: '', experience: '', workStatus: '', company: '', currentRole: '', tags: [], remark: '' })
const sources = ['BOSS直聘', '猎聘', '智联招聘', '内推', '朋友推荐', '校园招聘', '其他']
const experiences = ['应届生', '1年以内', '1—3年', '3—5年', '5—10年', '10年以上']
const talentTags = ['品牌设计', '视觉设计', '电商经验', '内容运营', '市场营销', '软件开发', '产品经理', '数据分析', '项目管理', '管理经验', '校招人才', '跨境业务', '可远程', '可出差']
const positions = ref([]), invitation = ref(null), loadingPositions = ref(true), positionError = ref('')
const attempted = ref(false), saving = ref(false), submitted = ref(false), error = ref('')
const hasContact = computed(() => [form.phone, form.wechat, form.email].some(value => String(value || '').trim()))
const selectedPosition = computed(() => positions.value.find(item => String(item.id) === String(form.jobId)))
const salaryValid = computed(() => form.salaryMin !== '' && form.salaryMax !== '' && Number(form.salaryMin) >= 0 && Number(form.salaryMax) >= Number(form.salaryMin))
function onWorkStatusChange() { if (form.workStatus === '离职') { form.company = ''; form.currentRole = '' } }

async function loadPositions() { loadingPositions.value = true; positionError.value = ''; try { if (token.value) { invitation.value = await getQuestionnaireInvitation(token.value); if (invitation.value.expired) throw new Error('这份问卷链接已过期，请联系 HR 重新发送。'); if (invitation.value.status === '已提交') throw new Error('这份问卷已经提交，无需重复填写。'); positions.value = [invitation.value.job]; form.name = invitation.value.recipientName || ''; form.email = invitation.value.recipientEmail || ''; form.jobId = invitation.value.job.id } else positions.value = await getPublicPositions() } catch (cause) { positionError.value = cause.response?.data?.message || cause.message || '岗位读取失败，请稍后刷新页面。' } finally { loadingPositions.value = false } }
onMounted(loadPositions)
async function submit() {
  attempted.value = true; error.value = ''
  if (!form.name.trim() || !form.source || !form.gender || !form.experience || !form.jobId || !hasContact.value || !salaryValid.value) { error.value = '请完成标有“必填”的项目，并至少留下一个联系方式。'; return }
  saving.value = true
  try { const payload = { ...form, jobId: Number(form.jobId), salaryMin: Number(form.salaryMin), salaryMax: Number(form.salaryMax) }; if (token.value) await submitQuestionnaireInvitation(token.value, payload); else await submitQuestionnaire(payload); submitted.value = true }
  catch (cause) { error.value = cause.response?.data?.message || cause.message || '提交失败，请稍后重试。' }
  finally { saving.value = false }
}
</script>

<template>
  <main class="questionnaire-page"><section class="questionnaire-card">
    <div class="questionnaire-brand"><BrandLockup /></div>
    <div v-if="submitted" class="submitted-state"><span>✓</span><h1>资料已提交</h1><p>你的档案和本次应聘经历已经建立，HR 会在合适的时间与你联系。</p></div>
    <template v-else><div class="questionnaire-heading"><p>人才登记问卷</p><h1>让我们先认识你</h1><span>{{ token ? '这是 HR 发给你的专属问卷。姓名、邮箱和应聘岗位已锁定，提交后 HR 会立即收到提醒。' : '岗位来自公司正在招聘的岗位库。带“必填”的项目用于建立完整档案和第一次应聘经历。' }}</span></div>
      <div v-if="invitation" class="invitation-banner"><span>专属邀请</span><strong>{{ invitation.job.company }} · {{ invitation.job.name }}</strong><small>收件邮箱：{{ invitation.recipientEmail }}</small></div>
      <form novalidate @submit.prevent="submit">
        <section><h2><i>01</i>基本信息</h2><div class="form-grid"><label :class="{ missing: attempted && !form.name.trim() }">姓名 / 常用称呼 <em>必填</em><input v-model.trim="form.name" :readonly="Boolean(invitation)" maxlength="100" placeholder="怎么称呼你" /></label><label>其他昵称<input v-model.trim="form.nickname" maxlength="100" placeholder="平台昵称或常用称呼" /></label></div>
          <TalentChoiceGroup v-model="form.gender" label="性别" :options="['男','女']" required :attempted="attempted" compact />
          <div class="contact-grid" :class="{ missing: attempted && !hasContact }"><p>联系方式 <em>至少填写一项</em></p><label>手机<input v-model.trim="form.phone" maxlength="18" placeholder="11 位手机号" /></label><label>微信<input v-model.trim="form.wechat" maxlength="20" placeholder="微信号" /></label><label>邮箱<input v-model.trim="form.email" :readonly="Boolean(invitation)" type="email" maxlength="200" placeholder="name@example.com" /></label></div>
          <TalentChoiceGroup v-model="form.source" label="你从哪里了解到我们" :options="sources" required :attempted="attempted" />
        </section>
        <section><h2><i>02</i>职业信息</h2><div class="form-grid"><label :class="{ missing: attempted && !form.experience }">工作经验 <em>必填</em><select v-model="form.experience"><option value="">请选择</option><option v-for="item in experiences" :key="item">{{ item }}</option></select></label><label>所在城市<input v-model.trim="form.location" maxlength="160" placeholder="例如：上海" /></label></div>
          <TalentChoiceGroup v-model="form.workStatus" label="当前任职状态" :options="['在职','离职']" compact @change="onWorkStatusChange" />
          <div v-if="form.workStatus === '在职'" class="form-grid"><label>当前公司<input v-model.trim="form.company" maxlength="200" /></label><label>当前职位<input v-model.trim="form.currentRole" maxlength="200" /></label></div>
          <TalentChoiceGroup v-model="form.tags" label="人才标签（可多选）" :options="talentTags" multiple />
        </section>
        <section><h2><i>03</i>本次应聘</h2><div class="form-grid"><label :class="{ missing: attempted && !form.jobId }">应聘岗位 <em>必填</em><select v-model="form.jobId" :disabled="loadingPositions || Boolean(invitation)"><option value="">{{ loadingPositions ? '正在读取岗位…' : '请选择岗位' }}</option><option v-for="job in positions" :key="job.id" :value="job.id">{{ job.company || '未设置公司' }} · {{ job.name }} · {{ job.recruitmentCode || job.id }}</option></select></label><label>首次接触日期<input v-model="form.applyTime" type="date" /></label></div>
          <div v-if="selectedPosition" class="position-preview"><strong>{{ selectedPosition.name }}</strong><span>{{ selectedPosition.company || '未设置公司' }} · {{ selectedPosition.department || '部门待补充' }}</span><p>{{ selectedPosition.minSalary ?? '—' }} — {{ selectedPosition.maxSalary ?? '—' }} K / 月 · {{ selectedPosition.baseLocation || selectedPosition.location || '地点待补充' }}</p><small>{{ selectedPosition.description || '暂无岗位介绍' }}</small></div>
          <div class="salary-field" :class="{ missing: attempted && !salaryValid }"><span>期望月薪 K / 月 <em>必填</em></span><div><input v-model="form.salaryMin" type="number" min="0" step="0.1" placeholder="最低" /><b>—</b><input v-model="form.salaryMax" type="number" min="0" step="0.1" placeholder="最高" /></div></div>
          <label>补充说明<textarea v-model.trim="form.remark" rows="4" maxlength="5000" placeholder="你希望 HR 了解的经历、能力或求职偏好" /></label>
        </section>
        <p v-if="positionError" class="questionnaire-error">{{ positionError }} <button type="button" class="retry" @click="loadPositions">重新读取</button></p><p v-if="error" class="questionnaire-error">{{ error }}</p><button class="submit-button" type="submit" :disabled="saving || loadingPositions">{{ saving ? '正在提交…' : '提交人才资料' }}</button>
      </form><p class="privacy-copy">提交后，资料只用于人才沟通和招聘流程。公司判断、招聘结果等内部信息由 HR 另行记录。</p>
    </template>
  </section></main>
</template>

<style scoped>
