fe3eb;border-radius:10px;background:#f7f8fa;color:#646a73;overflow:hidden}.source-options label.active{border-color:#9bb8ff;background:#e8f0ff;color:#245bdb}.source-options input{position:absolute;inset:0;opacity:0}.source-options span{display:block;padding:8px 11px;font-size:11px}.contact-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:11px;padding:15px;border:1px solid #e5e8ee;border-radius:15px}.contact-grid>p{grid-column:1/-1;margin:0;color:#4e5969;font-size:12px}.missing{border-color:#df7667!important;background:#fff3f1!important;animation:flash .42s ease 2}.questionnaire-error{margin:0;padding:11px 13px;border-radius:10px;background:#fff0ed;color:#b44f40;font-size:11px}.questionnaire-card button{border:0;border-radius:12px;padding:13px;background:#3370ff;color:#fff;font-size:13px;font-weight:600;box-shadow:0 8px 20px rgba(51,112,255,.22)}.questionnaire-card button:disabled{opacity:.55}.privacy-copy{text-align:center;color:#a0a6ad;font-size:10px;margin:18px 0 0}.submitted-state{text-align:center;padding:65px 10px}.submitted-state>span{display:grid;place-items:center;width:58px;height:58px;margin:auto;border-radius:50%;background:#e5f5ea;color:#28a745;font-size:27px}.submitted-state h1{margin:20px 0 10px}.submitted-state p{color:#7b8490;font-size:13px;line-height:1.8}@keyframes flash{50%{box-shadow:0 0 0 4px rgba(213,89,70,.17)}}@media(max-width:620px){.questionnaire-card{padding:25px 19px}.contact-grid{grid-template-columns:1fr}.questionnaire-heading h1{font-size:25px}}
.questionnaire-card{width:min(820px,100%)}.questionnaire-card form>section{padding:22px;border:1px solid #e7ebf1;border-radius:18px;background:#fff}.questionnaire-card h2{display:flex;align-items:center;gap:9px;margin:0 0 19px;font-size:16px}.questionnaire-card h2 i{padding:5px 7px;border-radius:7px;background:#edf3ff;color:#3370ff;font-size:9px;font-style:normal}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:15px}.questionnaire-card select,.questionnaire-card textarea{box-sizing:border-box;width:100%;border:1px solid #dfe3eb;border-radius:12px;padding:12px 13px;background:#f7f8fa;color:#1f2329;font:inherit;outline:0}.questionnaire-card textarea{resize:vertical}.questionnaire-card select:focus,.questionnaire-card textarea:focus{border-color:#3370ff;box-shadow:0 0 0 3px rgba(51,112,255,.11);background:#fff}.choice-options{display:flex;gap:7px;flex-wrap:wrap}.choice-options label{position:relative;border:1px solid #dfe3eb;border-radius:10px;background:#f7f8fa;color:#646a73;overflow:hidden}.choice-options label.active{border-color:#9bb8ff;background:#e8f0ff;color:#245bdb}.choice-options input{position:absolute;inset:0;opacity:0}.choice-options span{display:block;padding:8px 11px;font-size:11px}.position-preview{margin:16px 0;padding:15px;border-radius:13px;background:#eef4ff;color:#496079}.position-preview strong,.position-preview span,.position-preview small{display:block}.position-preview strong{color:#29496f;font-size:15px}.position-preview span{margin-top:5px;font-size:11px}.position-preview p{margin:9px 0;font-size:11px;font-weight:600}.position-preview small{line-height:1.7}.salary-field{display:grid;gap:8px;margin:16px 0;color:#4e5969;font-size:12px}.salary-field>div{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:9px}.salary-field b{color:#9aa4b0}.submit-button{border:0;border-radius:12px;padding:13px;background:#3370ff;color:#fff;font-size:13px;font-weight:600;box-shadow:0 8px 20px rgba(51,112,255,.22)}.retry{border:0!important;background:transparent!important;color:#2868e8!important;padding:0!important;box-shadow:none!important}@media(max-width:620px){.form-grid{grid-template-columns:1fr}.questionnaire-card form>section{padding:17px}}
.invitation-banner{display:grid;gap:5px;margin:-10px 0 22px;padding:16px 18px;border:1px solid #bacefd;border-radius:14px;background:#edf3ff}.invitation-banner span{color:#245bdb;font-size:10px;font-weight:700;letter-spacing:1px}.invitation-banner strong{color:#1f2329;font-size:16px}.invitation-banner small{color:#4e5969}.questionnaire-card input[readonly],.questionnaire-card select:disabled{background:#eef2f6!important;color:#374151!important;opacity:1}
.questionnaire-page{display:block;padding:46px 20px 70px;background:linear-gradient(135deg,#f4f7fb 0%,#edf3ff 48%,#f7f8fa 100%)}.questionnaire-card{width:min(860px,100%);margin:0 auto;padding:36px 42px;border:1px solid #dbe3ee;border-radius:24px;background:#fff;box-shadow:0 24px 70px rgba(38,62,101,.12)}.questionnaire-brand{padding-bottom:28px;border-bottom:1px solid #e5e9ef}.questionnaire-heading{margin:30px 0 25px}.questionnaire-heading p{margin-bottom:9px;color:#3370ff;font-size:10px;letter-spacing:1.3px}.questionnaire-heading h1{margin-bottom:10px;color:#172033;font-size:28px}.questionnaire-heading>span{display:block;color:#536174;font-size:13px;line-height:1.8}.questionnaire-card form{gap:22px}.questionnaire-card form>section{padding:25px;border-color:#d8e0e9;border-radius:16px;background:#fff}.questionnaire-card h2{margin-bottom:21px;color:#1f2937;font-size:16px}.questionnaire-card h2 i{background:#edf3ff;color:#245bdb}.questionnaire-card form>label,.contact-grid label{color:#344054;font-size:12px;font-weight:550}.questionnaire-card input,.questionnaire-card select,.questionnaire-card textarea{min-height:43px;border-color:#cfd8e3;background:#fff;color:#172033}.questionnaire-card input:focus,.questionnaire-card select:focus,.questionnaire-card textarea:focus{border-color:#3370ff;box-shadow:0 0 0 3px rgba(51,112,255,.12)}.contact-grid{margin-top:18px;border-color:#d8e0e9;background:#f8fafc}.contact-grid>p{color:#344054;font-weight:550}.position-preview{border:1px solid #d7e3f6;background:#f5f8ff}.salary-field{color:#344054;font-weight:550}.submit-button{min-height:46px;font-size:14px}.privacy-copy{color:#667085;font-size:11px}.submitted-state p{color:#536174}@media(max-width:620px){.questionnaire-page{padding:18px 10px 40px}.questionnaire-card{padding:24px 17px;border-radius:19px}.questionnaire-brand{padding-bottom:22px}.questionnaire-heading{margin:25px 0 22px}.questionnaire-heading h1{font-size:25px}.questionnaire-card form>section{padding:18px}.form-grid{grid-template-columns:1fr}.contact-grid{grid-template-columns:1fr}}
</style>
<style scoped>
.questionnaire-brand>.sethub-brand{display:inline-flex;width:auto;height:auto;border-radius:0;background:transparent;color:#172033;font-weight:400;box-shadow:none}
</style>
